def starter_articles():
    return [normalize_article(dict(title=title,source=source,date=date,url=url,text=summary+' '+details,
        source_kind="Официальная публикация",text_kind="Краткое изложение по источнику"))
        for title,source,date,url,summary,details in PUBLICATIONS]


def starter_summaries():
    return {normalize_article(dict(title=t,source=s,date=d,url=u,text=summary+' '+details))["id"]: summary
            for t,s,d,u,summary,details in PUBLICATIONS}


