def apply_prepared_analysis(cards):
    """Enrich only exact seed publications; never overwrite successful AI analysis."""
    prepared = {a['id']: (a, insight) for a, insight in zip(starter_articles(), PREPARED_ANALYSIS)}
    summaries = starter_summaries()
    for card in cards:
        match = prepared.get(card['id'])
        if match and card.get('generation_method') != 'llm' and card.get('text') == match[0]['text']:
            why_now, actions = match[1]
            card.update(summary=summaries[card['id']], why_now=why_now,
                        recommended_actions=list(actions), analysis_origin='prepared')
    return cards
